#ifndef DELETE_CONFIRM_H
#define DELETE_CONFIRM_H

#include <stdbool.h>
#include <stddef.h>
#include <stdint.h>

/* -----------------------------------------------------------------------
 * delete_confirm.h
 * TEAM CODE (owner: Tony - display and user interface) - written by the BJT2 team, not generated by STM32CubeMX.
 * Authors: written by Brendon (integrator) on 29-30 Oct 2026 for Tony's display/UI subsystem (best-ui), with an AI coding assistant.
 * BJT2 Sound Modulating Toy — Delete "Tap Again" Confirm
 *
 * What it does: the File screen's 4th row, "Delete", must never delete a
 * recording by accident. The first tap only ARMS it: the row turns red
 * and says "Sure? Tap again", and info line 2 asks "Delete REC05.WAV?".
 * A second tap 0.5 to 3 s later confirms, and the file that was armed
 * (never another one) is deleted. Anything else disarms it.
 *
 * Who runs it: TonyTask, through tony_ui.c (one confirm, s_dc). Pure
 * logic: no RTOS, no HAL, so it compiles on any host (tests:
 * test_delete_confirm.c). Times are passed in as tick counts (ms).
 *
 * Main steps:
 *   1. dc_press()        a tap on the Delete row: ARMED, IGNORED (too
 *                        soon) or CONFIRMED (send JACK_CMD_DELETE)
 *   2. dc_update()       on every pass: 3 s without a second tap disarm
 *   3. dc_name_changed() the selection moved to another file: disarm
 *   4. dc_cancel()       any other input, or the screen changed: disarm
 *   5. dc_label(), dc_prompt()  what the row and info line 2 say
 *
 * The states, and what moves between them:
 *
 *   from    event                                        to
 *   IDLE    dc_press with a name                         ARMED  (DC_PRESS_ARMED)
 *   ARMED   dc_press under DC_MIN_MS after arming,       ARMED  (DC_PRESS_IGNORED)
 *           for the same name
 *   ARMED   dc_press DC_MIN_MS up to DC_CONFIRM_MS        IDLE   (DC_PRESS_CONFIRMED:
 *           after arming, for the same name                      delete the armed name)
 *   ARMED   dc_press DC_CONFIRM_MS or later, or for       ARMED  (DC_PRESS_ARMED: a
 *           another name                                         new first tap)
 *   ARMED   dc_update DC_CONFIRM_MS after arming         IDLE   (timed out)
 *   ARMED   dc_name_changed to another name              IDLE
 *   ARMED   dc_cancel                                    IDLE
 * ----------------------------------------------------------------------- */

#define DC_MIN_MS       500U    /* a second tap sooner than this is ignored: rows 2 (Select) and
                                 * 3 (Delete), counting from 0, are only 2 px apart, and a press
                                 * ends ~80 ms after the finger lifts, so a quick double tap must
                                 * never delete */
#define DC_CONFIRM_MS   3000U   /* the armed row waits this long for the second tap */
#define DC_NAME_LEN     13U     /* an 8.3 name + NUL (= STORAGE_NAME_LEN, app_rtos.h) */
#define DC_LABEL_MAX    16U     /* characters a row label can show: a size-2 letter is 12 px wide
                                 * and the label starts 8 px into the 200 px row: (200 - 8) / 12 */
#define DC_PROMPT_MAX   20U     /* characters of a size-2 info line */

typedef enum {
    DC_IDLE = 0,        /* the row says "Delete"; nothing is armed */
    DC_ARMED            /* the first tap was seen: "Sure? Tap again" */
} dc_state_t;

/* What one tap on the Delete row did */
typedef enum {
    DC_PRESS_ARMED = 0,     /* a first tap: armed for this name */
    DC_PRESS_IGNORED,       /* too soon after the first tap (or no name): nothing changed */
    DC_PRESS_CONFIRMED      /* the second tap in time: delete the armed name */
} dc_press_t;

typedef struct {
    dc_state_t state;
    uint32_t   armed_ms;            /* tick count of the first tap */
    char       name[DC_NAME_LEN];   /* the raw name the first tap armed */
} delete_confirm_t;

/**
 * dc_init
 * IDLE. NULL: nothing happens.
 */
void dc_init(delete_confirm_t *dc);

/**
 * dc_press
 * One tap on the Delete row at now_ms, with name (raw) selected; the
 * table above says what it does. On DC_PRESS_CONFIRMED the ARMED name is
 * copied to armed_out and the confirm goes back to IDLE. A NULL or empty
 * name, a NULL dc, or (for a confirm) a NULL armed_out changes nothing and
 * gives DC_PRESS_IGNORED.
 */
dc_press_t dc_press(delete_confirm_t *dc, uint32_t now_ms, const char *name,
                    char armed_out[DC_NAME_LEN]);

/**
 * dc_update
 * Called on every pass: true when an armed confirm has just timed out
 * (DC_CONFIRM_MS after the first tap, also across the 32-bit tick wrap);
 * it is then IDLE. false otherwise.
 */
bool dc_update(delete_confirm_t *dc, uint32_t now_ms);

/**
 * dc_name_changed
 * The selection is now name (raw; NULL counts as ""). Another name than
 * the armed one disarms it.
 */
void dc_name_changed(delete_confirm_t *dc, const char *name);

/**
 * dc_cancel
 * Disarm (any other input, a screen change, the screen saver opening).
 */
void dc_cancel(delete_confirm_t *dc);

/**
 * dc_armed
 * true while ARMED (the row is red, info line 2 shows the prompt).
 */
bool dc_armed(const delete_confirm_t *dc);

/**
 * dc_label
 * The Delete row's label: "Sure? Tap again" while armed, else "Delete"
 * (at most DC_LABEL_MAX characters). Never NULL.
 */
const char *dc_label(const delete_confirm_t *dc);

/**
 * dc_prompt
 * Info line 2 while armed: "Delete REC05.WAV?", at most DC_PROMPT_MAX
 * characters ("Delete ABCDEFGH.WAV?"). name is the copy cleaned up for
 * the panel (the caller sanitizes it). NULL out: nothing happens.
 */
void dc_prompt(const char *name, char *out, size_t len);

#endif /* DELETE_CONFIRM_H */
